                stats[model]['hour']['input'] += inp
                stats[model]['hour']['output'] += out
                stats[model]['hour']['cache'] += cache

# only models with day/hour any data
stats = {k:v for k,v in stats.items() if any(v[p][m] for p in ('day','hour') for m in ('input','output','cache'))}
print(json.dumps(stats, ensure_ascii=False, indent=2))
