import os, json, glob, datetime
from collections import defaultdict

state_dir = os.path.expanduser('~/.openclaw')
agent_id = 'main'
session_dir = os.path.join(state_dir, 'agents', agent_id, 'sessions')

now = datetime.datetime(2026,4,28,10,28,0, tzinfo=datetime.timezone(datetime.timedelta(hours=8)))
start_day = now.replace(hour=0, minute=0, second=0, microsecond=0)
start_hour = now - datetime.timedelta(hours=1)

stats = defaultdict(lambda: {'day': {'input':0,'output':0,'cache':0}, 'hour': {'input':0,'output':0,'cache':0}})
for path in glob.glob(os.path.join(session_dir, '*.jsonl')):
    with open(path, 'r', encoding='utf-8') as f:
        for line in f:
            line = line.strip()
            if not line:
                continue
            try:
                obj = json.loads(line)
            except Exception:
                continue
            if obj.get('type') != 'message':
                continue
            msg = obj.get('message') or {}
            if msg.get('role') != 'assistant':
                continue
            usage = msg.get('usage') or {}
            if not usage:
                continue
            model = msg.get('model') or usage.get('model') or usage.get('modelId') or 'unknown'
            ts = obj.get('timestamp') or msg.get('timestamp')
            if not ts:
                continue
            try:
                dt = datetime.datetime.fromisoformat(ts.replace('Z', '+00:00')).astimezone(start_day.tzinfo)
            except Exception:
                continue
            inp = usage.get('input_tokens') or usage.get('inputTokens') or usage.get('input') or 0
            out = usage.get('output_tokens') or usage.get('outputTokens') or usage.get('output') or 0
            cache = usage.get('cache_read_input_tokens') or usage.get('cacheReadInputTokens') or usage.get('cache_read_tokens') or usage.get('cacheRead') or 0
            if dt >= start_day:
                stats[model]['day']['input'] += inp
                stats[model]['day']['output'] += out
                stats[model]['day']['cache'] += cache
            if dt >= start_hour:
                stats[model]['hour']['input'] += inp
                stats[model]['hour']['output'] += out
                stats[model]['hour']['cache'] += cache

models = [(k,v) for k,v in stats.items() if any(v[p][m] for p in ('day','hour') for m in ('input','output','cache'))]
models.sort(key=lambda kv: kv[0].lower())

def fmt(n):
    return f"{n/1_000_000:.3f}"

parts=[]
labels=['一','二','三','四','五','六','七','八','九','十']
for i,(model,v) in enumerate(models, start=1):
    label = labels[i-1] if i-1 < len(labels) else str(i)
    parts.append(f"模型{label}：{model}\n\n今日总输入量（M）：{fmt(v['day']['input'])}\n\n今日总输出量（M）：{fmt(v['day']['output'])}\n\n今日总缓存命中量（M）：{fmt(v['day']['cache'])}\n\n最近一小时：输入量（M）{fmt(v['hour']['input'])}、输出量（M）{fmt(v['hour']['output'])}、缓存命中量（M）{fmt(v['hour']['cache'])}")

print("\n\n".join(parts))
